// A minimal circuit breaker: fail fast while open, probe when half-open.
func (b *Breaker) Call(op func() error) error {
	b.mu.Lock()
	if time.Now().Before(b.openUntil) { // OPEN: fail fast, no call
		b.mu.Unlock()
		return errors.New("circuit open")
	}
	b.mu.Unlock()

	err := op() // CLOSED or HALF-OPEN: attempt the call
	b.mu.Lock()
	defer b.mu.Unlock()
	if err != nil {
		b.failures++
		if b.failures >= b.threshold {
			b.openUntil = time.Now().Add(5 * time.Second) // trip open
		}
		return err
	}
	b.failures = 0 // success closes the circuit
	return nil
}
